def _obfuscate_command(self,
                       command_args: Sequence[CommandArg],
                       obfuscate_args: Optional[Iterable[CommandArg]] = None,
                       regex_patterns: Optional[Iterable[str]] = None) -> ObfuscatedCommand:
    # Support regex expressions for matching
    obfuscate_args = set(chain((obfuscate_args or []), self.default_obfuscation))
    obfuscated = ' '.join(
        self.obfuscation if arg in obfuscate_args or any(re.match(pattern, str(arg)) for pattern in (regex_patterns or [])) else shlex.quote(str(arg))
        for arg in command_args)
    return ObfuscatedCommand(obfuscated)
